theorem regularizedKernelMatrix_symmetric {n : ℕ}
    (K : Matrix (Fin n) (Fin n) ℝ) (lambda : ℝ) (hK : Kᵀ = K) :
    (regularizedKernelMatrix K lambda)ᵀ = regularizedKernelMatrix K lambda

theorem covering_le_packing {eps : ℝ} {s : Set A}
    (heps : 0 < eps) (hs : TotallyBounded s) :
    coveringNumber eps s ≤ packingNumber eps s

theorem gamma2FiniteBound_nonneg {cardT : ℕ} {diamT C : ℝ}
    (hC : 0 ≤ C) (hD : 0 ≤ diamT) :
    0 ≤ gamma2FiniteBound cardT diamT C

theorem chainingWeight_mono (A : AdmissibleSequence) {i j : Fin A.depth}
    (h : i.val ≤ j.val) :
    A.chainingWeight i ≤ A.chainingWeight j

theorem massartBound_mono_n (cardF : ℕ) {n₁ n₂ : ℕ}
    (hF : 2 ≤ cardF) (hn₁ : 0 < n₁) (h : n₁ ≤ n₂) :
    massartBound cardF n₂ ≤ massartBound cardF n₁

theorem linearRademacherBound_nonneg {W X : ℝ} {n : ℕ}
    (hW : 0 ≤ W) (hX : 0 ≤ X) (_hn : 0 < n) :
    0 ≤ linearRademacherBound W X n

theorem linearRademacherBound_anti {W X : ℝ} {n₁ n₂ : ℕ}
    (hW : 0 < W) (hX : 0 < X) (hn₁ : 0 < n₁) (h : n₁ ≤ n₂) :
    linearRademacherBound W X n₂ ≤ linearRademacherBound W X n₁

theorem symmetrization_vc_pac_width (d n : ℕ) (_hn : 1 ≤ n) (_hd : 1 ≤ d)
    (δ : ℝ) (_hδ : 0 < δ) (_hδ1 : δ < 1) :
    let R_bound := Real.sqrt (2 * (Real.log (d + 1 : ℝ) + d * Real.log (n : ℝ)) / n)
    let t := Real.sqrt (2 * Real.log (1 / δ) / n)
    0 ≤ 2 * R_bound + t

theorem azuma_tail_from_sum_param {C δ : ℝ} (hC : 0 < C) (hδ : 0 < δ) (hδ1 : δ < 1) :
    let ε := Real.sqrt (2 * C * Real.log (1 / δ))
    ε ^ 2 / (2 * C) = Real.log (1 / δ)

theorem confidence_width_from_azuma {H : ℕ} {B δ : ℝ}
    (hH : 0 < H) (hB : 0 < B) (hδ : 0 < δ) (hδ1 : δ < 1) :
    let C := (H : ℝ) * B ^ 2
    let β := B * Real.sqrt (2 * H * Real.log (1 / δ))
    β ^ 2 / (2 * C) = Real.log (1 / δ)

theorem confidence_width_pos {H : ℕ} {B δ : ℝ}
    (hH : 0 < H) (hB : 0 < B) (hδ : 0 < δ) (hδ1 : δ < 1) :
    0 < B * Real.sqrt (2 * H * Real.log (1 / δ))

theorem azuma_tail_equals_delta {H : ℕ} {B δ : ℝ}
    (hH : 0 < H) (hB : 0 < B) (hδ : 0 < δ) (hδ1 : δ < 1) :
    let C := (H : ℝ) * B ^ 2
    let β := B * Real.sqrt (2 * H * Real.log (1 / δ))
    Real.exp (-(β ^ 2 / (2 * C))) = δ

theorem ucbvi_bonus_pos {c L : ℝ} {N : ℕ}
    (hc : 0 < c) (hL : 0 < L) :
    0 < c * Real.sqrt (L / (max N 1 : ℝ))

theorem bonus_decreasing_in_visits {L : ℝ} {N₁ N₂ : ℝ}
    (hL : 0 ≤ L) (hN₁ : 0 < N₁) (_hN₂ : 0 < N₂) (h : N₁ ≤ N₂) :
    Real.sqrt (L / N₂) ≤ Real.sqrt (L / N₁)

theorem gaussian_tail_inversion {δ : ℝ} (hδ : 0 < δ) (hδ1 : δ < 1) :
    let t := Real.sqrt (2 * Real.log (1 / δ))
    Real.exp (gaussianConcentration.isoExponent t) = δ

theorem bernsteinRate_nonneg {σ_sq b a : ℝ}
    (hσ : 0 < σ_sq) (hb : 0 ≤ b) :
    0 ≤ bernsteinRate σ_sq b a

theorem ldBernsteinExponent_nonpos {n : ℕ} {σ_sq b a : ℝ}
    (hσ : 0 < σ_sq) (hb : 0 ≤ b) :
    ldBernsteinExponent n σ_sq b a ≤ 0

theorem bernstein_rate_le_quadratic {σ_sq b a : ℝ}
    (hσ : 0 < σ_sq) (hb : 0 ≤ b) :
    bernsteinRate σ_sq b a ≤ quadraticRate σ_sq a

theorem matrixBernsteinExponent_nonneg {sigma_sq b t : ℝ}
    (hsigma : 0 < sigma_sq) (hb : 0 < b) (ht : 0 ≤ t) :
    0 ≤ matrixBernsteinExponent sigma_sq b t

theorem matrix_bernstein_confidence_width
    {sigma_sq b : ℝ}
    (hsigma : 0 < sigma_sq) (_hb : 0 < b)
    {L : ℝ} (_hL : 0 ≤ L) :
    let t := Real.sqrt sigma_sq * Real.sqrt (2 * L) + b * (2 * L / 3)
    t ^ 2 ≤ 2 * (sigma_sq * (2 * L) + (b * (2 * L / 3)) ^ 2)

theorem abs_diff_le_of_mem_Icc {a b x y : ℝ}
    (hx : x ∈ Set.Icc a b) (hy : y ∈ Set.Icc a b) :
    |x - y| ≤ b - a

theorem subgaussian_implies_subexponential {c b : ℝ}
    (hc : 0 ≤ c) (hb : 0 < b) {lam : ℝ} (hlam : |lam| ≤ 1 / b) :
    lam ^ 2 * c / 2 ≤ c / (2 * b ^ 2)

theorem subgaussian_two_sided_inversion {c δ : ℝ}
    (hc : 0 < c) (hδ : 0 < δ) (hδ2 : δ < 2) :
    let t := Real.sqrt (2 * c * Real.log (2 / δ))
    t ^ 2 / (2 * c) = Real.log (2 / δ)

theorem subexponential_tail_transition {ν_sq b : ℝ}
    (hb : 0 < b) (hν : 0 < ν_sq) :
    (ν_sq / b) ^ 2 / (2 * ν_sq) = ν_sq / (2 * b ^ 2)

theorem hasSubgaussianMGF_of_bounded {X : Ω → ℝ} {a b : ℝ}
    (hm : AEMeasurable X μ) (hb : ∀ᵐ ω ∂μ, X ω ∈ Set.Icc a b) :
    ProbabilityTheory.HasSubgaussianMGF (fun ω ↦ X ω - μ[X]) ((‖b - a‖₊ / 2) ^ 2) μ

theorem weightedHamming_nonneg {indicator : Fin n → ℝ}
    (h_ind : ∀ i, 0 ≤ indicator i) :
    0 ≤ cd.weightedHamming indicator

theorem weightedHamming_le_hamming {indicator : Fin n → ℝ}
    (_h_ind_le : ∀ i, indicator i ≤ 1) (h_ind_nn : ∀ i, 0 ≤ indicator i) :
    cd.weightedHamming indicator ≤ ∑ i : Fin n, indicator i

theorem talagrand_exponent_at_threshold {δ : ℝ} (hδ : 0 < δ) (hδ2 : δ < 2) :
    let t := 2 * sqrt (log (2 / δ))
    talagrandExponent t = -log (2 / δ)

theorem talagrand_tail_equals_delta {δ : ℝ} (hδ : 0 < δ) (hδ2 : δ < 2) :
    let t := 2 * sqrt (log (2 / δ))
    2 * exp (talagrandExponent t) = δ

theorem ConcreteFiniteMDP.toFiniteMDP_γ {n m : ℕ} {hn : 0 < n} {hm : 0 < m}
    (C : ConcreteFiniteMDP n m hn hm) :
    C.toFiniteMDP.γ = C.γ

theorem ConcreteFiniteMDP.valueIterationQ_zero {n m : ℕ} {hn : 0 < n} {hm : 0 < m}
    (C : ConcreteFiniteMDP n m hn hm) (s : Fin n) (a : Fin m) :
    C.toFiniteMDP.valueIterationQ 0 s a = 0

theorem SmallMDP.toFiniteMDP_well_formed
    {n m : ℕ} {hn : 0 < n} {hm : 0 < m}
    {hn_small : n ≤ 20} {hm_small : m ≤ 5}
    (S : SmallMDP n m hn hm hn_small hm_small) :
    S.toFiniteMDP.γ = S.γ

theorem SmallMDP.valueIterationQ_zero
    {n m : ℕ} {hn : 0 < n} {hm : 0 < m}
    {hn_small : n ≤ 20} {hm_small : m ≤ 5}
    (S : SmallMDP n m hn hm hn_small hm_small)
    (s : Fin n) (a : Fin m) :
    S.toFiniteMDP.valueIterationQ 0 s a = 0

theorem projectedValue_eq_linearValue {d : ℕ}
    (approx : M.LinearApprox d) (θ : Fin d → ℝ) :
    M.projectedValue approx θ = M.linearValue approx.φ θ

theorem le_cam_fano_comparison
    (Delta I : ℝ) (_hDelta : 0 < Delta) (_hI : 0 ≤ I)
    (_hI_small : I < Real.log 2) :
    let fano_bound := Delta * (1 - (I + Real.log 2) / Real.log 2)
    let le_cam_style := -(Delta * I / Real.log 2)
    fano_bound = le_cam_style

theorem weighted_geom_sum_le (n : ℕ) {γ : ℝ}
    (hγ_nn : 0 ≤ γ) (hγ_lt : γ < 1) :
    ∑ k ∈ Finset.range n, (↑k : ℝ) * γ ^ k ≤ γ / (1 - γ) ^ 2

theorem abs_csInf_image_sub_csInf_image_le {α : Type*} {s : Set α}
    (hs : s.Nonempty) {f g : α → ℝ} {ε : ℝ}
    (hf : BddBelow (f '' s)) (hg : BddBelow (g '' s))
    (h : ∀ x ∈ s, |f x - g x| ≤ ε) :
    |sInf (f '' s) - sInf (g '' s)| ≤ ε

theorem softmax_centered_feature_mean_zero {d : ℕ}
    (φ : M.S → M.A → Fin d → ℝ) (θ : Fin d → ℝ) (s : M.S) (i : Fin d) :
    ∑ a, M.softmaxProb φ θ s a * M.softmaxCenteredFeature φ θ s a i = 0

theorem gradient_domination_nonneg {d : ℕ}
    (gd : GradientDomination d) (θ : Fin d → ℝ) :
    0 ≤ gd.J gd.θ_star - gd.J θ
